package org.apache.commons.lang3;

import java.io.*;
import java.lang.reflect.Array;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import org.apache.commons.lang3.builder.EqualsBuilder;
import org.apache.commons.lang3.builder.ToStringBuilder;
import org.apache.commons.lang3.builder.ToStringStyle;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ArrayUtils.add(T[] array, int index, T element)
 */
public class ArrayUtils_add_TriageGen1Test {

    @Test
    public void testAdd_StringArray_Middle() {
        String[] array = {"a", "c"};
        String[] result = ArrayUtils.add(array, 1, "b");
        String[] expected = {"a", "b", "c"};
        assertArrayEquals(expected, result);
        assertEquals(String.class, result.getClass().getComponentType());
    }

    @Test
    public void testAdd_StringArray_Start() {
        String[] array = {"b", "c"};
        String[] result = ArrayUtils.add(array, 0, "a");
        String[] expected = {"a", "b", "c"};
        assertArrayEquals(expected, result);
    }

    @Test
    public void testAdd_StringArray_End() {
        String[] array = {"a", "b"};
        String[] result = ArrayUtils.add(array, 2, "c");
        String[] expected = {"a", "b", "c"};
        assertArrayEquals(expected, result);
    }

    @Test
    public void testAdd_IntegerArray() {
        Integer[] array = {1, 3};
        Integer[] result = ArrayUtils.add(array, 1, 2);
        Integer[] expected = {1, 2, 3};
        assertArrayEquals(expected, result);
        assertEquals(Integer.class, result.getClass().getComponentType());
    }

    @Test
    public void testAdd_NullArray_WithElement() {
        // Covers: if (array != null) is false, else if (element != null) is true
        String[] result = ArrayUtils.add(null, 0, "new");
        String[] expected = {"new"};
        assertArrayEquals(expected, result);
        assertEquals(String.class, result.getClass().getComponentType());
    }

    @Test
    public void testAdd_NullArray_WithNullElement() {
        // Covers: if (array != null) is false, else if (element != null) is false
        // Returns (T[]) new Object[] { null }
        Object[] result = ArrayUtils.add(null, 0, null);
        assertNotNull(result);
        assertEquals(1, result.length);
        assertNull(result[0]);
        assertEquals(Object.class, result.getClass().getComponentType());
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testAdd_IndexOutOfBounds_TooHigh() {
        String[] array = {"a"};
        ArrayUtils.add(array, 5, "b");
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testAdd_IndexOutOfBounds_Negative() {
        String[] array = {"a"};
        ArrayUtils.add(array, -1, "b");
    }

    @Test
    public void testAdd_EmptyArray() {
        String[] array = {};
        String[] result = ArrayUtils.add(array, 0, "a");
        String[] expected = {"a"};
        assertArrayEquals(expected, result);
    }
}
